messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
        #ui {
            position: absolute;
            top: 20px;
            left: 50%;
            transform: translateX(-50%);
            color: white;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            font-size: 24px;
            font-weight: bold;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="ui">RACE IN PROGRESS</div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 200;
        const FINISH_LINE_Z = -100;
        const START_LINE_Z = 100;
        const CAR_SCALE = 1.5;
        const RACE_DURATION = 600; // Frames approx
        const RESET_DURATION = 200; // Frames approx

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky Blue
        scene.fog = new THREE.Fog(0x87CEEB, 50, 250);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 500);
        camera.position.set(0, 15, 120);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(10, 20, 20);
        dirLight.castShadow = true;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(1000, 1000);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.8 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.5;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track Markings
        const lineGeo = new THREE.PlaneGeometry(2, 300);
        const lineMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const centerLine = new THREE.Mesh(lineGeo, lineMat);
        centerLine.rotation.x = -Math.PI / 2;
        centerLine.position.y = 0.01;
        scene.add(centerLine);

        // Finish Line (Checkerboard pattern)
        const finishGeo = new THREE.PlaneGeometry(30, 4);
        const finishCanvas = document.createElement('canvas');
        finishCanvas.width = 128;
        finishCanvas.height = 128;
        const ctx = finishCanvas.getContext('2d');
        ctx.fillStyle = 'white';
        ctx.fillRect(0,0,128,128);
        ctx.fillStyle = 'black';
        ctx.fillRect(0,0,64,64);
        ctx.fillRect(64,64,64,64);
        const finishTex = new THREE.CanvasTexture(finishCanvas);
        finishTex.wrapS = THREE.RepeatWrapping;
        finishTex.wrapT = THREE.RepeatWrapping;
        finishTex.repeat.set(4, 1);
        const finishMat = new THREE.MeshBasicMaterial({ map: finishTex });
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.02, FINISH_LINE_Z);
        scene.add(finishLine);

        // Finish Arch
        const archGroup = new THREE.Group();
        const pillarGeo = new THREE.BoxGeometry(1, 8, 1);
        const pillarMat = new THREE.MeshStandardMaterial({ color: 0x888888 });
        const leftPillar = new THREE.Mesh(pillarGeo, pillarMat);
        leftPillar.position.set(-10, 4, FINISH_LINE_Z);
        const rightPillar = new THREE.Mesh(pillarGeo, pillarMat);
        rightPillar.position.set(10, 4, FINISH_LINE_Z);
        const bannerGeo = new THREE.BoxGeometry(20, 2, 1);
        const bannerMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
        const banner = new THREE.Mesh(bannerGeo, bannerMat);
        banner.position.set(0, 7, FINISH_LINE_Z);
        const textGeo = new THREE.PlaneGeometry(16, 1.5);
        const textCanvas = document.createElement('canvas');
        textCanvas.width = 256;
        textCanvas.height = 64;
        const tCtx = textCanvas.getContext('2d');
        tCtx.fillStyle = 'white';
        tCtx.font = 'bold 40px Arial';
        tCtx.textAlign = 'center';
        tCtx.fillText("FINISH", 128, 45);
        const textTex = new THREE.CanvasTexture(textCanvas);
        const textMat = new THREE.MeshBasicMaterial({ map: textTex });
        const textPlane = new THREE.Mesh(textGeo, textMat);
        textPlane.position.set(0, 7, FINISH_LINE_Z + 0.51);
        archGroup.add(leftPillar, rightPillar, banner, textPlane);
        scene.add(archGroup);

        // --- Car Factory ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Body
            const bodyGeo = new THREE.BoxGeometry(2, 1, 4);
            const bodyMat = new THREE.MeshStandardMaterial({ color: color });
            const body = new THREE.Mesh(bodyGeo, bodyMat);
            body.position.y = 0.5;
            body.castShadow = true;
            carGroup.add(body);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.8, 0.6, 2);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = 1.3;
            cabin.position.z = -0.2;
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
            const wheels = [
                { x: -1.1, y: 0.4, z: 1.2 },
                { x: 1.1, y: 0.4, z: 1.2 },
                { x: -1.1, y: 0.4, z: -1.2 },
                { x: 1.1, y: 0.4, z: -1.2 }
            ];

            wheels.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, pos.y, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            return carGroup;
        }

        // --- Cars ---
        const redCar = createCar(0xFF0000); // Bright Red
        const blueCar = createCar(0x0000FF); // Bright Blue
        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation State ---
        let frame = 0;
        let state = 'RACING'; // RACING, FINISHED, RESETTING
        let raceStartTime = 0;
        let winner = '';

        // Easing function for smoother movement
        function easeInOutCubic(t) {
            return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
        }

        function updateCars() {
            if (state === 'RACING') {
                // Normalize time 0 to 1
                const t = Math.min(frame / RACE_DURATION, 1);

                // Blue Car Logic: Starts strong, maintains lead, then slows slightly
                // Position = Start + (Distance * Progress)
                // Blue starts at x = -5, Red at x = 5
                let blueProgress = t;
                // Add some wobble to speed
                if (t > 0.2 && t < 0.8) {
                    // Blue slows down slightly in the middle
                    blueProgress = t * 0.95;
                }
                // Blue actually finishes first at t=1, but Red overtakes visually
                // To make Red win, Red must have higher position (lower Z) at t=1
                // Let's adjust: Blue leads early (0.0 to 0.4), Red overtakes (0.5), Red wins (0.8+)

                // Blue Path: Fast start, steady finish
                let blueZ = START_LINE_Z + (FINISH_LINE_Z - START_LINE_Z) * easeInOutCubic(t);

                // Red Path: Slow start, fast middle, wins
                // We want Red to be behind Blue at t=0.4, and ahead at t=0.6
                let redZ = START_LINE_Z + (FINISH_LINE_Z - START_LINE_Z) * easeInOutCubic(t);

                // Adjust Z based on "Speed" curve
                // Blue speed curve: High early, constant
                // Red speed curve: Low early, High middle
                // We can simply offset Z based on a curve difference

                // Difference curve: Positive means Blue is ahead (more negative Z)
                // At t=0, Diff=0. At t=0.3, Diff=Max (Blue leads). At t=0.7, Diff=Min (Red leads).
                const diffCurve = Math.sin(t * Math.PI * 2.5) * 15; // Amplitude of 15 units

                // Blue is at x = -5, Red is at x = 5
                blueCar.position.set(-5, 0, blueZ);
                redCar.position.set(5, 0, redZ - diffCurve); // Red subtracts diff, so if diff is positive, Red is behind (higher Z)

                // Tilt cars slightly for visual flair
                blueCar.rotation.z = 0.05; // Lean into turn or just style
                redCar.rotation.z = -0.05;

                // Check win condition
                if (t >= 1) {
                    // Determine winner based on Z position (lower Z is closer to finish)
                    if (redCar.position.z < blueCar.position.z) {
                        winner = "RED";
                        document.getElementById('ui').innerText = "RED WINS!";
                    } else {
                        winner = "BLUE";
                        document.getElementById('ui').innerText = "BLUE WINS!";
                    }
                    state = 'FINISHED';
                    frame = 0;
                }

            } else if (state === 'FINISHED') {
                // Hold position for a moment
                if (frame > 120) {
                    state = 'RESETTING';
                    frame = 0;
                    document.getElementById('ui').innerText = "RACE IN PROGRESS";
                }
            } else if (state === 'RESETTING') {
                // Reset positions smoothly
                const resetT = Math.min(frame / RESET_DURATION, 1);
                const currentZ = START_LINE_Z; // Just snap back for simplicity or lerp

                // Simple lerp back to start
                const startZ = 100;
                const endZ = 100; // They start at 100

                // Actually, let's just teleport them back quickly or fade out
                // Teleport is easiest for a loop
                redCar.position.set(5, 0, START_LINE_Z);
                blueCar.position.set(-5, 0, START_LINE_Z);

                // Reset rotation
                redCar.rotation.z = -0.05;
                blueCar.rotation.z = 0.05;

                state = 'RACING';
                frame = 0;
            }

            frame++;
        }

        function animate() {
            requestAnimationFrame(animate);
            updateCars();

            // Camera Logic
            // Camera follows the average position of the two cars
            const avgZ = (redCar.position.z + blueCar.position.z) / 2;
            const avgX = (redCar.position.x + blueCar.position.x) / 2;

            // Target camera position
            const camTargetZ = avgZ + 30; // Behind the cars
            const camTargetX = avgX * 0.5; // Slightly centered but follows lateral movement
            const camTargetY = 15;

            // Smooth camera movement
            camera.position.z += (camTargetZ - camera.position.z) * 0.1;
            camera.position.x += (camTargetX - camera.position.x) * 0.1;
            camera.position.y += (camTargetY - camera.position.y) * 0.1;

            // Look at the cars
            camera.lookAt(avgX, 0, avgZ - 20);

            renderer.render(scene, camera);
        }

        // Handle Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start Animation
        animate();

    </script>
</body>
</html>
